import { apiClient, ApiError } from "@/lib/apiClient";

// apiv3 token-kapsamlı ödeme talebi oluşturma (POST /bookings/{ref}/payment-request?token=).
// Legacy servis hatada parse edilmiş gövdeyi döndürüyordu (.then(res=>res.json())); davranışı
// koru: 4xx'te (kart validasyonu vb.) hata gövdesini döndür, fırlatma.
export default async function postPaymentRequest({
  reference_id,
  token,
  requestParameters,
}: {
  reference_id: string;
  token: string;
  requestParameters: any;
}) {
  try {
    return await apiClient(
      `/bookings/${reference_id}/payment-request?token=${token}`,
      { method: "POST", body: requestParameters }
    );
  } catch (e) {
    if (e instanceof ApiError) {
      return e.body ?? {};
    }
    throw e;
  }
}
