  "tw-w-full tw-px-3.5 tw-py-2.5 tw-rounded-[10px] tw-text-[15px] tw-text-[#14101c] tw-outline-none tw-border tw-border-solid placeholder:tw-text-[#8a8398] tw-bg-white disabled:tw-opacity-50";

// Live card-brand detection from the leading digits (IIN ranges) so the matching
// scheme logo can surface inside the card-number field as the user types.
function detectCardBrand(num: string): { src: string; alt: string } | null {
  const n = (num || "").replace(/\D/g, "");
  if (!n) return null;
  if (/^4/.test(n)) return { src: "visa.svg", alt: "Visa" };
  if (/^(5[1-5]|2[2-7])/.test(n))
    return { src: "master-card.svg", alt: "Mastercard" };
  if (/^(5018|502|503|56|57|58|6[03-9])/.test(n))
    return { src: "maestro.svg", alt: "Maestro" };
  return null;
}

// Luhn checksum — catches typos / numbers that don't match the card standard
// before we ever hit the payment gateway.
function luhnValid(digits: string): boolean {
  let sum = 0;
  let alt = false;
  for (let i = digits.length - 1; i >= 0; i--) {
    let d = parseInt(digits[i], 10);
    if (alt) {
      d *= 2;
      if (d > 9) d -= 9;
    }
    sum += d;
    alt = !alt;
  }
  return sum % 10 === 0;
}

function isValidCardNumber(digits: string): boolean {
  return digits.length >= 13 && digits.length <= 19 && luhnValid(digits);
}

// Card-number field geometry without a border colour, so the valid/error colour
// can be applied conditionally without two competing border utilities.
const cardFieldBase =
  "tw-w-full tw-py-2.5 tw-pl-11 tw-rounded-[10px] tw-text-[15px] tw-text-[#14101c] tw-outline-none tw-border tw-border-solid placeholder:tw-text-[#8a8398] tw-bg-white disabled:tw-opacity-50";

// Pickup/dropoff arrive as full ISO timestamps (e.g. 2026-06-18T05:30:00.000000Z)
// — show only HH:MM, taking the literal time part (no timezone shift).
function formatTime(t?: string): string {
  if (!t) return "";
  const iso = String(t).match(/T(\d{2}):(\d{2})/);
  if (iso) return `${iso[1]}:${iso[2]}`;
  const hm = String(t).match(/^(\d{1,2}):(\d{2})/);
  if (hm) return `${hm[1].padStart(2, "0")}:${hm[2]}`;
  return String(t);
}

