export default function Page({ referenceId }: { referenceId: string }) {
  const router = useRouter();
  const searchParams = useSearchParams();
  const [detailsLoading, setDetailsLoading] = useState(true);
  const [paymentRequestLoading, setPaymentRequestLoading] = useState(true);
  const [submitLoading, setSubmitLoading] = useState(false);
  const [amountModalOpen, setAmountModalOpen] = useState(false);
  const [routeCount, setRouteCount] = useState<number | null>(null);
  const [submitTried, setSubmitTried] = useState(false);
  const [formErrors, setFormErrors] = useState<{ [key: string]: string[] }>({});

  const [data, setData] = useState({
    id: 0,
    start_date: "",
    subject: "",
    token: "",
    service_type: "",
    seller_currency: "",
    buyer_currency: "",
    can_pay_deposit: false,
    amounts: {
      buyer: {
        coupon_amount: 0,
        discount_amount: 0,
        final_amount: 0,
        original_amount: 0,
        paid_amount: 0,
        remaining_amount: 0,
        total_discount: 0,
        deposit_amount: 0,
      },
      seller: {
        coupon_amount: 0,
        discount_amount: 0,
        final_amount: 0,
        original_amount: 0,
        paid_amount: 0,
        remaining_amount: 0,
        total_discount: 0,
        deposit_amount: 0,
      },
    },
    tour: {
      id: 0,
      name: "",
      slug: "",
      image: "",
      startsAt: "",
      endsAt: "",
      start_location: "",
      end_location: "",
      pickup_time: "",
      dropoff_time: "",
      suitable_ages: "",
      duration_days: 0,
      languages: [{ id: 0, name: "" }],
      defaults: { accommodation: false },
      guide_type: { name: { en: "" } },
    },
    items: [],
    applied_promo_code: null as { code: string; discount: number } | null,
    payment_model: "",
    card_name: "",
    card_number: "",
    exp_month: 0,
    exp_year: 0,
    cvc: "",
  });

  // Kod uygulandığında/kaldırıldığında sunucudan dönen güncel tutarlar. Depozito
  // seçimi de yeniden türetilir; aksi halde eski tutarla ödeme talebi açılırdı.
  const handlePromoAmounts = (
    amounts: any,
    applied: { code: string; discount: number } | null,
  ) => {
    if (!amounts?.buyer) return;

    setData((prev) => ({
      ...prev,
      amounts,
      applied_promo_code: applied,
      payment_model:
        prev.can_pay_deposit && amounts.buyer.deposit_amount > 0
          ? prev.payment_model || "deposit"
          : "total",
    }));
  };

  const [paymentRequestData, setPaymentRequestData] = useState({
    status: "",
    // Müşteri beklemeli mi — kararı API veriyor (bkz. BookingPaymentRequestResource).
    // `null` = henüz bilmiyoruz.
    inProgress: null as boolean | null,
    details: "",
    amount: 0,
    currency: "",
    reference_id: "",
    // Başarısızlıkta tahsilatın olmadığını biliyor muyuz? (apiv3 outcome_certain)
    outcomeCertain: true,
  });

  const fetchDetails = async () => {
    await getPaymentDetail(referenceId, searchParams.get("token")!).then(
      (res) => {
        setData({
          ...data,
          id: res.data.id,
          start_date: res.data.start_date,
          subject: res.data.subject,
          token: res.data.token,
          service_type: res.data.service_type,
          seller_currency: res.data.seller_currency,
          buyer_currency: res.data.buyer_currency,
          can_pay_deposit: res.data.can_pay_deposit,
          amounts: res.data.amounts,
          applied_promo_code: res.data.applied_promo_code ?? null,
          payment_model:
            res.data.can_pay_deposit &&
            res.data.amounts.buyer.deposit_amount > 0
              ? "deposit"
              : "total",
          tour: {
            ...data.tour,
            id: res.data.tour.id,
            name: res.data.tour.name,
            slug: res.data.tour.slug,
            image: res.data.tour.image,
            start_location: res.data.tour.start_location,
            end_location: res.data.tour.end_location,
            pickup_time: res.data.tour.pickup_time,
            dropoff_time: res.data.tour.dropoff_time,
            suitable_ages: res.data.tour.suitable_ages,
            duration_days: res.data.tour.duration_days,
            languages: res.data.tour.languages,
            defaults: res.data.tour.defaults,
            guide_type: res.data.tour.guide_type,
          },
          items: res.data.items,
        });

        setDetailsLoading(false);

        // Routes/destination count isn't part of the payment payload — fetch it
        // separately (best-effort) for the trip summary meta.
        getTourDetail(res.data.tour.slug)
          .then((td: any) => {
            if (Array.isArray(td?.routes)) setRouteCount(td.routes.length);
          })
          .catch(() => {});
      },
    );
  };

  const fetchPaymentRequest = async () => {
    if (
      searchParams.has("request_id") &&
      searchParams.get("request_id") !== "" &&
      searchParams.has("request_token") &&
      searchParams.get("request_token") !== ""
    ) {
      await getPaymentRequestDetail(
        referenceId,
        searchParams.get("request_id")!,
        searchParams.get("request_token")!,
      )
        .then((res) => {
          setPaymentRequestData({
            status: res.data.status,
            inProgress: res.data.in_progress ?? null,
            details: res.data.details,
            amount: res.data.amount ?? 0,
            currency: res.data.currency ?? "",
            reference_id: res.data.reference_id ?? "",
            outcomeCertain: res.data.outcome_certain !== false,
          });

          setPaymentRequestLoading(false);
        })
        // Geçici bir ağ hatası yoklamayı bitirmemeli: bir sonraki turda tekrar denenir.
        .catch(() => {});
    }
  };

  const submitForm = async () => {
    if (data.amounts.buyer.remaining_amount > 0) {
      const digits = (data.card_number || "").replace(/\D/g, "");
      const cvc = (data.cvc || "").replace(/\D/g, "");
      const incomplete =
        !isValidCardNumber(digits) ||
        !data.card_name.trim() ||
        !(data.exp_month > 0) ||
        !(data.exp_year > 0) ||
        cvc.length < 3;
      if (incomplete) {
        setSubmitTried(true);
        return;
      }
    }
    setFormErrors({});
    setSubmitLoading(true);

    try {
      const response = await postPaymentRequest({
        reference_id: referenceId,
        token: searchParams.get("token") || "",
        requestParameters: {
          payment_model: data.payment_model,
          card_name: data.card_name,
          card_number: data.card_number,
          exp_month: data.exp_month,
          exp_year: data.exp_year,
          cvc: data.cvc,
        },
      });

      if (response.success) {
        const form = document.createElement("form");
        form.method = "POST";
        // Ödeme artık kendi altyapımızda (apiv3 /payments/pay) — eski
        // payment.travelshopbooking.com servisine gitmiyor.
        form.action = `${process.env.NEXT_PUBLIC_APIV3_URL}/payments/pay`;

        /*
         * Banka dönüşü AYRI bir sayfaya iner: /payment/check. apiv3 orada yalnızca
         * imzayı doğrulayıp provizyonu kuyruğa veriyor; o sayfa sonucu yoklar ve
         * belli olunca buraya geri getirir. Böylece müşteri ne bekleme ekranı ile
         * ödeme formu arasında sıçrama görür ne de ödeme sonrası bayat tutarlar.
         */
        const bookingToken = searchParams.get("token") || "";
        const returnUrl =
          `${window.location.origin}/booking/${referenceId}/payment/check` +
          `?token=${encodeURIComponent(bookingToken)}` +
          `&request_id=${response.data.id}` +
          `&request_token=${encodeURIComponent(response.data.token)}`;

        // Tutar ve banka gönderilmez — ikisini de apiv3 belirler (tutar ödeme
        // talebinden, banka sunucu yapılandırmasından). Sonuç da dönüş adresinde
        // taşınmaz; sayfa request_id/request_token ile durumu API'den çeker.
        const paymentPostData = {
          reference: response.data.reference_id,
          return_url: returnUrl,
          card_name: data.card_name,
          card_number: data.card_number,
          exp_month: data.exp_month,
          exp_year: data.exp_year,
          cvc: data.cvc,
        };

        (
          Object.keys(paymentPostData) as Array<keyof typeof paymentPostData>
        ).forEach((key) => {
          const input = document.createElement("input");
          input.type = "hidden";
          input.name = key;
          input.value = String(paymentPostData[key]);
          form.appendChild(input);
        });

        document.body.appendChild(form);
        form.submit();
      } else {
        if (response.errors) {
          setFormErrors(response.errors);
          window.scrollTo({ top: 0, behavior: "smooth" });
          setSubmitLoading(false);
        }
      }
    } catch (error) {
      setFormErrors({
        general: ["Payment request failed"],
      });
      setSubmitLoading(false);
    }
  };

  useEffect(() => {
    fetchDetails();
    fetchPaymentRequest();
  }, []); // eslint-disable-line react-hooks/exhaustive-deps

  /*
   * Bekleme bu sayfanın işi değil (bkz. /payment/check). Buraya yine de süren bir ödeme
   * düşerse — eski bir bağlantı ya da bankanın dönüşü tekrarlaması — müşteri ödeme
   * formuyla baş başa bırakılmaz, bekleme sayfasına devredilir.
   *
   * Koşul bekleme sayfasınınkinin tam tersi (ikisi de `in_progress` alanına bakar), bu
   * yüzden iki sayfa arasında yönlendirme döngüsü oluşamaz.
   */
  useEffect(() => {
    if (paymentRequestData.inProgress !== true) return;

    router.replace(
      `/booking/${referenceId}/payment/check` +
        `?token=${encodeURIComponent(searchParams.get("token") ?? "")}` +
        `&request_id=${encodeURIComponent(searchParams.get("request_id") ?? "")}` +
        `&request_token=${encodeURIComponent(searchParams.get("request_token") ?? "")}`,
    );
  }, [paymentRequestData.inProgress]); // eslint-disable-line react-hooks/exhaustive-deps

  // Tarih saat dilimi kaymasına karşı güvenli biçimlendirilir (bkz. helpers/plainDate.ts).
  const getFullDate = (date: string | Date) => formatPlainDate(date);

  const fmt = (amount: number) =>
    priceFormat({
      amount,
      currency: data.buyer_currency,
      maximumFractionDigits: 2,
    });

  const cardBrand = detectCardBrand(data.card_number);
  const cardDigits = (data.card_number || "").replace(/\D/g, "");
  const cvcDigits = (data.cvc || "").replace(/\D/g, "");
  // Don't nag mid-typing: only flag when the *prefix* can't be any scheme
  // (başını hatalı yazmış), when a full 16-digit number fails Luhn, or once the
  // user tries to submit.
  const cardComplete = cardDigits.length === 16;
  const invalidPrefix = cardDigits.length >= 1 && !/^[2-6]/.test(cardDigits);
  const cardInvalid =
    invalidPrefix ||
    (cardComplete && !luhnValid(cardDigits)) ||
    (submitTried && !isValidCardNumber(cardDigits));
  // Inline hint only for a genuinely malformed number (wrong scheme prefix or a
  // completed number failing Luhn). An "incomplete on submit" number is already
  // covered by the red border + the summary alert, so no extra line there.
  const cardFormatError =
    invalidPrefix || (cardComplete && !luhnValid(cardDigits));

  // Remaining required-field errors only surface after a submit attempt.
  const nameError = submitTried && !data.card_name.trim();
  const monthError = submitTried && !(data.exp_month > 0);
  const yearError = submitTried && !(data.exp_year > 0);
  const cvcError = submitTried && cvcDigits.length < 3;
  const hasFieldErrors =
    cardInvalid || nameError || monthError || yearError || cvcError;

  const borderState = (err: boolean) =>
    err
      ? "tw-border-[#e3342f] focus:tw-border-[#e3342f]"
      : "tw-border-[#d8d2e1] focus:tw-border-[#854ec9]";

  const cardFieldCls = `${cardFieldBase} ${
    cardBrand ? "tw-pr-16" : "tw-pr-3.5"
  } ${borderState(cardInvalid)}`;
  const holderFieldCls = `${iconFieldBase} ${borderState(nameError)}`;
  const cvcFieldCls = `${plainFieldBase} ${borderState(cvcError)}`;

  // react-select control turns red when the select is required-but-empty on submit.
  const selectStylesFor = (err: boolean) =>
    err
      ? {
          ...bookingSelectStyles,
          control: (base: any, state: any) => ({
            ...(bookingSelectStyles.control as any)(base, state),
            borderColor: "#e3342f",
            boxShadow: state.isFocused
              ? "0 0 0 3px rgba(227,52,47,0.15)"
              : "none",
            ":hover": { borderColor: "#e3342f" },
          }),
        }
      : bookingSelectStyles;

  const monthOptions: SelectOption[] = Array.from({ length: 12 }, (_, i) => {
    const m = (i + 1).toString().padStart(2, "0");
    return { value: m, label: m };
  });
  const yearOptions: SelectOption[] = Array.from({ length: 11 }, (_, i) => {
    const y = new Date().getFullYear() + i;
    return { value: y.toString().slice(-2), label: y.toString() };
  });

  const shellCls = "tw-mx-auto tw-max-w-[1320px] tw-px-4 tw-py-6 tw-font-display";

  const backLink = (
    <a
      href={"/booking/" + referenceId + "?token=" + data.token}
      className="tw-inline-flex tw-items-center tw-gap-1 tw-text-[13.5px] tw-font-semibold tw-text-[#854ec9] tw-no-underline hover:tw-underline"
    >
      <svg width="18" height="18" fill="currentColor" viewBox="0 0 16 16">
        <path
          fillRule="evenodd"
          d="M12 8a.5.5 0 0 1-.5.5H5.707l2.147 2.146a.5.5 0 0 1-.708.708l-3-3a.5.5 0 0 1 0-.708l3-3a.5.5 0 1 1 .708.708L5.707 7.5H11.5a.5.5 0 0 1 .5.5"
        />
      </svg>
      Back to Booking
    </a>
  );

  if (detailsLoading)
    return (
      <main>
        <div className={shellCls}>
          <Breadcrumb
            items={[
              { pageTitle: "Booking & Enquiry", pageUrl: "" },
              { pageTitle: "Your Trip", pageUrl: "" },
              { pageTitle: "Payment Details", pageUrl: "" },
            ]}
          />
          {backLink}
          <h3 className={`${pageTitleCls} tw-mt-2`}>Payment Detail</h3>
          <div className="tw-flex tw-flex-col tw-items-center tw-gap-4 tw-py-20 tw-text-[#5d556c]">
            <span className="tw-inline-block tw-h-12 tw-w-12 tw-animate-spin tw-rounded-full tw-border-4 tw-border-solid tw-border-[#854ec9] tw-border-r-transparent" />
            <p className="tw-m-0 tw-text-center tw-text-[15px]">
              Loading your order details.
              <br />
              Please wait.
            </p>
          </div>
        </div>
      </main>
    );

  const rowCls =
    "tw-flex tw-justify-between tw-gap-3 tw-py-2.5 tw-border-0 tw-border-b tw-border-solid tw-border-[#f0edf5] tw-text-[14px]";
  const viewDetailsBtn = (
    <button
      type="button"
      onClick={() => setAmountModalOpen(true)}
      className="tw-border-0 tw-bg-transparent tw-p-0 tw-text-[13px] tw-font-semibold tw-text-[#854ec9] tw-cursor-pointer hover:tw-underline"
    >
      View Details
    </button>
  );

  return (
    <main>
      <div className={shellCls}>
        <Breadcrumb
          items={[
            { pageTitle: "Booking & Enquiry", pageUrl: "" },
            {
              pageTitle: data.subject,
              pageUrl: "/booking/" + referenceId + "?token=" + data.token,
            },
            { pageTitle: "Payment Details", pageUrl: "" },
          ]}
        />
        {backLink}
        <div className="tw-mt-2 tw-flex tw-flex-wrap tw-items-center tw-justify-between tw-gap-3">
          <h3 className={pageTitleCls}>Payment Detail</h3>
          <span className="tw-inline-flex tw-items-center tw-gap-1.5 tw-text-[13px] tw-font-semibold tw-text-[#1ea672]">
            {ic.lock} Secure payment
          </span>
        </div>

        <div className="tw-mt-5 tw-grid tw-grid-cols-1 tw-gap-5 lg:tw-grid-cols-12">
          <div className="lg:tw-col-span-8">
            {searchParams.has("request_id") &&
            searchParams.has("request_token") ? (
              paymentRequestLoading ? null : paymentRequestData.status ===
                "success" ? (
                <Success />
              ) : paymentRequestData.status === "failed" ? (
                // Yalnızca gerçekten reddedilmiş ödeme için. `pending` (ör. banka
                // sayfasında yarım bırakılmış deneme) "başarısız" gibi gösterilmez.
                <Failed paymentRequestData={paymentRequestData} />
              ) : null
            ) : null}

            <div className="tw-relative tw-mb-4 tw-min-h-[160px] tw-overflow-hidden tw-rounded-2xl lg:tw-hidden">
              {data.tour.image && (
                <Image
                  src={data.tour.image}
                  alt={data.subject}
                  fill
                  sizes="100vw"
                  quality={90}
                  className="tw-object-cover"
                />
              )}
              <div
                className="tw-absolute tw-inset-0"
                style={{
                  background:
                    "linear-gradient(to top, rgba(20,16,28,0.88) 0%, rgba(20,16,28,0.40) 55%, rgba(20,16,28,0.12) 100%)",
                }}
              />
              <div className="tw-relative tw-flex tw-min-h-[160px] tw-flex-col tw-justify-end tw-p-4">
                <span className="tw-text-[10.5px] tw-font-bold tw-uppercase tw-tracking-[0.12em] tw-text-white/70">
                  Your trip
                </span>
                <h4 className="tw-mb-2 tw-mt-1 tw-text-[17px] tw-font-bold tw-leading-tight tw-text-white">
                  {data.subject}
                </h4>
                <div className="tw-flex tw-flex-wrap tw-items-center tw-gap-x-4 tw-gap-y-1 tw-text-[12.5px] tw-font-medium tw-text-white/85">
                  {data.tour.duration_days > 0 && (
                    <span className="tw-inline-flex tw-items-center tw-gap-1.5">
                      <svg
                        width="14"
                        height="14"
                        viewBox="0 0 16 16"
                        fill="currentColor"
                      >
                        <path d="M8 3.5a.5.5 0 0 0-1 0V9a.5.5 0 0 0 .252.434l3.5 2a.5.5 0 0 0 .496-.868L8 8.71z" />
                        <path d="M8 16A8 8 0 1 0 8 0a8 8 0 0 0 0 16m7-8A7 7 0 1 1 1 8a7 7 0 0 1 14 0" />
                      </svg>
                      {data.tour.duration_days === 1
                        ? "Daily"
                        : `${data.tour.duration_days} Days`}
                    </span>
                  )}
                  {routeCount != null && routeCount > 0 && (
                    <span className="tw-inline-flex tw-items-center tw-gap-1.5">
                      <svg
                        width="14"
                        height="14"
                        viewBox="0 0 16 16"
                        fill="currentColor"
                      >
                        <path d="M15.817.113A.5.5 0 0 1 16 .5v14a.5.5 0 0 1-.402.49l-5 1a.5.5 0 0 1-.196 0L5.5 15.01l-4.902.98A.5.5 0 0 1 0 15.5v-14a.5.5 0 0 1 .402-.49l5-1a.5.5 0 0 1 .196 0L10.5.99l4.902-.98a.5.5 0 0 1 .415.103M10 1.91l-4-.8v12.98l4 .8zm1 12.98 4-.8V1.11l-4 .8zm-6-.8V1.11l-4 .8v12.98z" />
                      </svg>
                      {routeCount} {routeCount === 1 ? "Destination" : "Destinations"}
                    </span>
                  )}
                </div>
              </div>
            </div>

            {Object.keys(formErrors).length > 0 && (
              <div className="tw-mb-4 tw-rounded-[10px] tw-bg-[#fdecec] tw-px-4 tw-py-3 tw-text-[13.5px] tw-text-[#b23838]">
                <p className="tw-m-0 tw-mb-1 tw-font-semibold">
                  Please check the following errors:
                </p>
                <ul className="tw-m-0 tw-pl-4">
                  {Object.entries(formErrors).map(([field, errors]) =>
                    errors.map((error, index) => (
                      <li key={`${field}-${index}`}>{error}</li>
                    )),
                  )}
                </ul>
              </div>
            )}

            <div className={`${cardCls} tw-p-5`}>
              <h4 className={`${cardTitleCls} tw-mb-2`}>Your payment summary</h4>

              <div className="tw-mt-2">
                {data.amounts.buyer.final_amount !=
                  data.amounts.buyer.original_amount && (
                  <div className={rowCls}>
                    <span className="tw-text-[#3f3a4d]">
                      Total Amount ({viewDetailsBtn})
                    </span>
                    <span className="tw-font-medium tw-text-[#14101c]">
                      {fmt(data.amounts.buyer.original_amount)}
                    </span>
                  </div>
                )}
                {data.amounts.buyer.discount_amount > 0 && (
                  <div className={rowCls}>
                    <span className="tw-text-[#b23838]">
                      Discounts ({viewDetailsBtn})
                    </span>
                    <span className="tw-font-medium tw-text-[#b23838]">
                      - {fmt(data.amounts.buyer.discount_amount)}
                    </span>
                  </div>
                )}
                {data.amounts.buyer.coupon_amount > 0 && (
                  <div className={rowCls}>
                    <span className="tw-text-[#b23838]">Promo Code Discount</span>
                    <span className="tw-font-medium tw-text-[#b23838]">
                      - {fmt(data.amounts.buyer.coupon_amount)}
                    </span>
                  </div>
                )}
                <div className={rowCls}>
                  <span className="tw-text-[#3f3a4d]">Amount to Pay</span>
                  <span className="tw-font-bold tw-text-[#14101c]">
                    {fmt(data.amounts.buyer.final_amount)}
                  </span>
                </div>
                {data.amounts.buyer.paid_amount > 0 && (
                  <div className={rowCls}>
                    <span className="tw-text-[#1f8a4c]">Amount Paid</span>
                    <span className="tw-font-medium tw-text-[#1f8a4c]">
                      {fmt(data.amounts.buyer.paid_amount)}
                    </span>
                  </div>
                )}
                {data.amounts.buyer.remaining_amount > 0 && (
                  <div className="tw-flex tw-justify-between tw-gap-3 tw-py-3 tw-text-[16px]">
                    <span className="tw-font-bold tw-text-[#14101c]">
                      Remaining Amount
                    </span>
                    <span className="tw-text-[20px] tw-font-bold tw-text-[#854ec9]">
                      {fmt(data.amounts.buyer.remaining_amount)}
                    </span>
                  </div>
                )}
                {/* Kod kutusu ödeme yapılmamışsa görünür; ödenmiş rezervasyon
                    yeniden fiyatlandırılmaz (sunucu da reddeder). */}
                {data.amounts.buyer.paid_amount <= 0 && data.token && (
                  <PromoCodeBox
                    referenceId={referenceId}
                    token={data.token}
                    applied={data.applied_promo_code}
                    currency={data.buyer_currency}
                    onAmounts={handlePromoAmounts}
                  />
                )}

                {data.can_pay_deposit &&
                  data.amounts.buyer.deposit_amount > 0 && (
                    <>
                      <div className="tw-flex tw-justify-between tw-gap-3 tw-py-2 tw-text-[15px]">
                        <span className="tw-text-[#3f3a4d]">Deposit (25%)</span>
                        <span className="tw-text-[18px] tw-font-bold tw-text-[#14101c]">
                          {fmt(data.amounts.buyer.deposit_amount)}
                        </span>
                      </div>
                      <div className="tw-mt-3 tw-flex tw-flex-col tw-gap-2.5">
                        <label className="tw-flex tw-cursor-pointer tw-items-center tw-justify-end tw-gap-2 tw-text-[14px] tw-text-[#2a2336]">
                          I want to pay 25% deposit of the total amount
                          <input
                            type="radio"
                            name="paymentModel"
                            value="deposit"
                            className="tw-accent-[#854ec9]"
                            onClick={() =>
                              setData({ ...data, payment_model: "deposit" })
                            }
                            defaultChecked={data.payment_model === "deposit"}
                          />
                        </label>
                        <label className="tw-flex tw-cursor-pointer tw-items-center tw-justify-end tw-gap-2 tw-text-[14px] tw-text-[#2a2336]">
                          I want to pay the full amount
                          <input
                            type="radio"
                            name="paymentModel"
                            value="total"
                            className="tw-accent-[#854ec9]"
                            onClick={() =>
                              setData({ ...data, payment_model: "total" })
                            }
                            defaultChecked={data.payment_model === "total"}
                          />
                        </label>
                      </div>
                    </>
                  )}
              </div>
            </div>

            {data.amounts.buyer.remaining_amount > 0 && (
              <div className={`${cardCls} tw-my-4 tw-p-5`}>
                <h4 className={`${cardTitleCls} tw-mb-1`}>Add payment details</h4>
                <p className="tw-mb-4 tw-text-[13.5px] tw-text-[#6b6577]">
                  Complete your order by providing your payment details.
                </p>
                {submitTried && hasFieldErrors && (
                  <div className="tw-mb-4 tw-flex tw-items-center tw-gap-2 tw-rounded-[10px] tw-bg-[#fdecec] tw-px-4 tw-py-3 tw-text-[13.5px] tw-font-medium tw-text-[#b23838]">
                    <svg
                      width="16"
                      height="16"
                      viewBox="0 0 16 16"
                      fill="currentColor"
                      className="tw-shrink-0"
                    >
                      <path d="M8 15A7 7 0 1 1 8 1a7 7 0 0 1 0 14zm0 1A8 8 0 1 0 8 0a8 8 0 0 0 0 16z" />
                      <path d="M7.002 11a1 1 0 1 1 2 0 1 1 0 0 1-2 0zM7.1 4.995a.905.905 0 1 1 1.8 0l-.35 3.507a.552.552 0 0 1-1.1 0z" />
                    </svg>
                    Please fill in all required payment details.
                  </div>
                )}
                <div className="tw-grid tw-grid-cols-1 tw-gap-4 md:tw-grid-cols-2">
                  <div>
                    <label className={labelCls}>
                      Card Number <span className="tw-text-[#b23838]">*</span>
                    </label>
                    <div className="tw-relative">
                      <span
                        className={`tw-pointer-events-none tw-absolute tw-left-3.5 tw-top-1/2 tw--translate-y-1/2 ${
                          cardInvalid ? "tw-text-[#e3342f]" : "tw-text-[#9b95a8]"
                        }`}
                      >
                        {ic.card}
                      </span>
                      <MaskedInput
                        className={cardFieldCls}
                        maskGenerator={createDefaultMaskGenerator(
                          "9999-9999-9999-9999",
                        )}
                        placeholder="____-____-____-____"
                        value={data.card_number}
                        autoComplete="off"
                        onChange={(val) => {
                          setData({ ...data, card_number: val });
                        }}
                      />
                      {cardBrand && (
                        // eslint-disable-next-line @next/next/no-img-element
                        <img
                          src={`/images/footer/${cardBrand.src}`}
                          alt={cardBrand.alt}
                          className="tw-pointer-events-none tw-absolute tw-right-3 tw-top-1/2 tw--translate-y-1/2 tw-h-5 tw-w-auto"
                        />
                      )}
                    </div>
                    {cardFormatError && (
                      <p className="tw-m-0 tw-mt-1.5 tw-flex tw-items-center tw-gap-1 tw-text-[12.5px] tw-text-[#e3342f]">
                        <svg
                          width="13"
                          height="13"
                          viewBox="0 0 16 16"
                          fill="currentColor"
                        >
                          <path d="M8 15A7 7 0 1 1 8 1a7 7 0 0 1 0 14zm0 1A8 8 0 1 0 8 0a8 8 0 0 0 0 16z" />
                          <path d="M7.002 11a1 1 0 1 1 2 0 1 1 0 0 1-2 0zM7.1 4.995a.905.905 0 1 1 1.8 0l-.35 3.507a.552.552 0 0 1-1.1 0z" />
                        </svg>
                        Please enter a valid card number.
                      </p>
                    )}
                  </div>
                  <div>
                    <label className={labelCls}>
                      Card Holder <span className="tw-text-[#b23838]">*</span>
                    </label>
                    <div className="tw-relative">
                      <span className="tw-pointer-events-none tw-absolute tw-left-3.5 tw-top-1/2 tw--translate-y-1/2 tw-text-[#9b95a8]">
                        {ic.user}
                      </span>
                      <input
                        type="text"
                        className={holderFieldCls}
                        name="card_name"
                        placeholder="Full name on card"
                        defaultValue={data.card_name}
                        autoComplete="off"
                        onChange={(e) => {
                          setData({ ...data, card_name: e.target.value });
                        }}
                      />
                    </div>
                  </div>
                </div>
                <div className="tw-mt-4 tw-grid tw-grid-cols-2 tw-gap-4 sm:tw-grid-cols-3">
                  <div>
                    <label className={labelCls}>
                      Month <span className="tw-text-[#b23838]">*</span>
                    </label>
                    <Select<SelectOption>
                      instanceId="exp-month"
                      inputId="exp-month"
                      styles={selectStylesFor(monthError)}
                      options={monthOptions}
                      placeholder="MM"
                      value={
                        monthOptions.find(
                          (o) => parseInt(String(o.value), 10) === data.exp_month,
                        ) || null
                      }
                      onChange={(opt) =>
                        setData({
                          ...data,
                          exp_month: opt ? parseInt(String(opt.value), 10) : 0,
                        })
                      }
                    />
                  </div>
                  <div>
                    <label className={labelCls}>
                      Year <span className="tw-text-[#b23838]">*</span>
                    </label>
                    <Select<SelectOption>
                      instanceId="exp-year"
                      inputId="exp-year"
                      styles={selectStylesFor(yearError)}
                      options={yearOptions}
                      placeholder="YYYY"
                      value={
                        yearOptions.find(
                          (o) => parseInt(String(o.value), 10) === data.exp_year,
                        ) || null
                      }
                      onChange={(opt) =>
                        setData({
                          ...data,
                          exp_year: opt ? parseInt(String(opt.value), 10) : 0,
                        })
                      }
                    />
                  </div>
                  <div className="tw-col-span-2 sm:tw-col-span-1">
                    <label className={labelCls}>
                      CVV/CVC <span className="tw-text-[#b23838]">*</span>
                    </label>
                    <MaskedInput
                      name="cvc"
                      className={cvcFieldCls}
                      maskGenerator={createDefaultMaskGenerator("999")}
                      placeholder="___"
                      autoComplete="off"
                      value={data.cvc}
                      onChange={(val) => {
                        setData({ ...data, cvc: val });
                      }}
                    />
                  </div>
                </div>

                <div className="tw-mt-5 tw-flex tw-flex-col tw-gap-3 tw-border-0 tw-border-t tw-border-solid tw-border-[#ebe7f0] tw-pt-4 sm:tw-flex-row sm:tw-items-center sm:tw-justify-between">
                  <span className="tw-inline-flex tw-items-center tw-gap-1.5 tw-text-[12.5px] tw-text-[#8a8398]">
                    {ic.lock} 256-bit SSL encryption · 3D Secure
                  </span>
                  <div className="tw-flex tw-items-center tw-gap-2">
                    {[
                      { src: "visa.svg", alt: "Visa", cls: "tw-h-6" },
                      { src: "master-card.svg", alt: "Mastercard", cls: "tw-h-7" },
                      { src: "maestro.svg", alt: "Maestro", cls: "tw-h-7" },
                    ].map((c) => (
                      // eslint-disable-next-line @next/next/no-img-element
                      <img
                        key={c.src}
                        src={`/images/footer/${c.src}`}
                        alt={c.alt}
                        className={`${c.cls} tw-w-auto`}
                      />
                    ))}
                  </div>
                </div>
              </div>
            )}

            {data.amounts.buyer.remaining_amount > 0 && (
              <div className="tw-mb-12 tw-mt-4 tw-flex tw-flex-col tw-items-center tw-gap-6 tw-rounded-2xl tw-border tw-border-solid tw-border-[#e9e1f7] tw-bg-[#faf7fe] tw-p-5 sm:tw-flex-row sm:tw-justify-between sm:tw-gap-4">
                <div className="tw-text-center sm:tw-text-left">
                  <div className="tw-text-[12px] tw-font-semibold tw-uppercase tw-tracking-wide tw-text-[#8a8398]">
                    Amount to be Paid
                  </div>
                  <div className="tw-mt-1 tw-text-[30px] tw-font-bold tw-leading-none tw-text-[#854ec9]">
                    {data.can_pay_deposit &&
                    data.amounts.buyer.deposit_amount > 0 &&
                    data.payment_model === "deposit"
                      ? fmt(data.amounts.buyer.deposit_amount)
                      : fmt(data.amounts.buyer.remaining_amount)}
                  </div>
                  {data.can_pay_deposit &&
                    data.amounts.buyer.deposit_amount > 0 &&
                    data.payment_model === "deposit" && (
                      <div className="tw-mt-1.5 tw-text-[12.5px] tw-text-[#6b6577]">
                        25% deposit — remaining balance due later
                      </div>
                    )}
                </div>
                <button
                  type="button"
                  className={`${primaryBtnCls} tw-w-full tw-py-3 tw-text-[15px] sm:tw-w-auto sm:tw-min-w-[240px] sm:tw-px-10`}
                  onClick={submitForm}
                  disabled={submitLoading}
                >
                  {submitLoading ? (
                    <>
                      <span className={spinnerCls} />
                      Loading...
                    </>
                  ) : (
                    <>
                      Pay now
                      <svg
                        width="22"
                        height="22"
                        fill="currentColor"
                        viewBox="0 0 16 16"
                      >
                        <path
                          fillRule="evenodd"
                          d="M1 8a.5.5 0 0 1 .5-.5h11.793l-3.147-3.146a.5.5 0 0 1 .708-.708l4 4a.5.5 0 0 1 0 .708l-4 4a.5.5 0 0 1-.708-.708L13.293 8.5H1.5A.5.5 0 0 1 1 8"
                        />
                      </svg>
                    </>
                  )}
                </button>
              </div>
            )}
          </div>

          <div className="tw-hidden lg:tw-col-span-4 lg:tw-block">
            <div className="tw-sticky tw-top-[96px]">
              <div className={`${cardCls} tw-overflow-hidden`}>
                <div className="tw-relative tw-h-[170px] tw-w-full tw-bg-[#f0eef4]">
                  {data.tour.image && (
                    <Image
                      src={data.tour.image}
                      alt={data.tour.name || data.subject}
                      fill
                      quality={100}
                      loading="lazy"
                      className="tw-object-cover"
                      sizes="420px"
                    />
                  )}
                  <div className="tw-absolute tw-inset-0 tw-bg-gradient-to-t tw-from-[rgba(20,16,28,0.78)] tw-to-transparent" />
                  {data.service_type === "private" && (
                    <span className="tw-absolute tw-left-3 tw-top-3 tw-inline-block tw-rounded-full tw-bg-white/90 tw-px-2.5 tw-py-1 tw-text-[11px] tw-font-bold tw-uppercase tw-tracking-[0.04em] tw-text-[#854ec9]">
                      Private Tour
                    </span>
                  )}
                  <h2 className="tw-absolute tw-bottom-3 tw-left-4 tw-right-4 tw-m-0 tw-font-display tw-text-[16px] tw-font-bold tw-text-white tw-drop-shadow">
                    {data.subject}
                  </h2>
                </div>
                <div className="tw-px-5 tw-pb-4 tw-pt-4">
                  <div className="tw-divide-y tw-divide-[#f3f1f7]">
                    {(() => {
                      const startsIn = [
                        data.tour.start_location,
                        data.start_date ? getFullDate(data.start_date) : "",
                      ]
                        .filter(Boolean)
                        .join(", ");
                      return startsIn ? (
                        <DetailRow icon={ic.pin} label="Starts in" value={startsIn} />
                      ) : null;
                    })()}
                    {(() => {
                      const endDateStr = data.start_date
                        ? data.tour.duration_days > 1
                          ? getFullDate(
                              addPlainDays(
                                data.start_date,
                                data.tour.duration_days - 1,
                              ),
                            )
                          : getFullDate(data.start_date)
                        : "";
                      const endsIn = [data.tour.end_location, endDateStr]
                        .filter(Boolean)
                        .join(", ");
                      return endsIn ? (
                        <DetailRow icon={ic.pin} label="Ends in" value={endsIn} />
                      ) : null;
                    })()}
                    {data.tour.duration_days > 0 && (
                      <DetailRow
                        icon={ic.calendar}
                        label="Duration"
                        value={`${data.tour.duration_days} Days`}
                      />
                    )}
                    {formatTime(data.tour.pickup_time) && (
                      <DetailRow
                        icon={ic.clock}
                        label="Pick up time"
                        value={formatTime(data.tour.pickup_time)}
                      />
                    )}
                    {formatTime(data.tour.dropoff_time) && (
                      <DetailRow
                        icon={ic.clock}
                        label="Drop off time"
                        value={formatTime(data.tour.dropoff_time)}
                      />
                    )}
                    {(() => {
                      const operatedIn = (data.tour.languages || [])
                        .map((i: any) => i.name)
                        .filter(Boolean)
                        .join(", ");
                      return operatedIn ? (
                        <DetailRow
                          icon={ic.globe}
                          label="Operated in"
                          value={operatedIn}
                        />
                      ) : null;
                    })()}
                    {data.tour.guide_type?.name?.en && (
                      <DetailRow
                        icon={ic.user}
                        label="Guide type"
                        value={data.tour.guide_type.name.en}
                      />
                    )}
                    {data.tour.suitable_ages && (
                      <DetailRow
                        icon={ic.info}
                        label="Suitable ages"
                        value={data.tour.suitable_ages}
                      />
                    )}
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
        <PaymentDetailsModal
          data={data}
          open={amountModalOpen}
          onClose={() => setAmountModalOpen(false)}
        />
      </div>
    </main>
  );
}
