/**
 * Başarısız ödeme bildirimi.
 *
 * Tasarım kararları:
 *  - Bankanın çevrilmiş ret sebebi (`details`) ASIL mesajdır; başlığın hemen altında,
 *    nötr renkte durur — kırmızı bir duvar metni değil, okunabilir bir bilgi olsun diye.
 *  - Genel "kartınızı kontrol edin" listesi YALNIZCA sebep bilinmiyorsa gösterilir.
 *    Sebep belliyken (ör. "3D şifresi yanlış") o liste hem çelişir hem dikkat dağıtır.
 *  - "Kartınızdan çekim yapılmadı" satırı bilinçli: başarısız ödemede müşterinin ilk
 *    korkusu budur ve destek yükünün büyük kısmı bu sorudan gelir. AMA yalnızca bunu
 *    BİLDİĞİMİZDE yazılır: banka "reddettim" dediyse çekim yoktur, bankadan hiç cevap
 *    gelmediyse (zaman aşımı) tahsilatın olup olmadığını bilmiyoruz ve müşteriye
 *    yanlış güvence verilemez (apiv3 `outcome_certain`).
 */
export default function Failed({
  paymentRequestData,
}: {
  paymentRequestData: {
    status?: string;
    details?: string | null;
    outcomeCertain?: boolean;
  };
}) {
  const reason = paymentRequestData?.details?.trim();
  // Bankanın kararını biliyor muyuz? (false = cevap hiç gelmedi, sonuç belirsiz)
  const outcomeKnown = paymentRequestData?.outcomeCertain !== false;

  return (
    <div
      role="alert"
      className="tw-mb-5 tw-flex tw-gap-3.5 tw-rounded-2xl tw-border tw-border-solid tw-border-[#f2cccc] tw-bg-[#fef7f7] tw-p-4 tw-font-display sm:tw-p-5"
    >
      <span className="tw-mt-0.5 tw-flex tw-h-9 tw-w-9 tw-shrink-0 tw-items-center tw-justify-center tw-rounded-full tw-bg-[#fbe3e3] tw-text-[#c0392b]">
        <svg width="18" height="18" viewBox="0 0 16 16" fill="currentColor" aria-hidden="true">
          <path d="M8.982 1.566a1.13 1.13 0 0 0-1.96 0L.165 13.233c-.457.778.091 1.767.98 1.767h13.713c.889 0 1.438-.99.98-1.767zM8 5c.535 0 .954.462.9.995l-.35 3.507a.552.552 0 0 1-1.1 0L7.1 5.995A.905.905 0 0 1 8 5m.002 6a1 1 0 1 1 0 2 1 1 0 0 1 0-2" />
        </svg>
      </span>

      <div className="tw-min-w-0">
        <h4 className="tw-m-0 tw-text-[15.5px] tw-font-bold tw-text-[#8f2f27]">
          We couldn&apos;t complete your payment
        </h4>

        <p className="tw-m-0 tw-mt-1.5 tw-text-[14px] tw-leading-relaxed tw-text-[#3f3a4d]">
          {reason || 'Your bank declined the payment without giving a reason.'}
        </p>

        <p className="tw-m-0 tw-mt-2.5 tw-text-[13px] tw-text-[#6b6577]">
          {outcomeKnown
            ? "Your card has not been charged. Enter your details below to try again, or use a different card."
            : "Our team is checking this payment with the bank and will email you shortly. Please do not try again until you hear from us."}
        </p>

        {/* Sebep bilinmiyorsa elimizdeki tek yardım bu genel liste. */}
        {!reason && outcomeKnown && (
          <ul className="tw-m-0 tw-mt-2.5 tw-list-disc tw-pl-4 tw-text-[13px] tw-leading-relaxed tw-text-[#6b6577]">
            <li>Check that the card number, expiry date and CVV are correct.</li>
            <li>Make sure the card has enough available limit.</li>
            <li>Confirm with your bank that the card is open to international purchases.</li>
          </ul>
        )}
      </div>
    </div>
  );
}
